  margin: 0;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

[data-ui-component="ai-agent-request"] [data-ui-part="approval-details"] code,
[data-ui-component="ai-agent-request"] [data-ui-part="approval-diff"] {
  border: 1px solid var(--border);
  border-radius: 0.375rem;
  background: var(--muted);
  color: var(--foreground);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.75rem;
}

[data-ui-component="ai-agent-request"] [data-ui-part="approval-details"] code {
  align-self: flex-start;
  padding: 0.125rem 0.375rem;
}

[data-ui-component="ai-agent-request"] [data-ui-part="approval-diff"] {
  max-height: 12rem;
  margin: 0;
  overflow: auto;
  padding: 0.5rem;
  white-space: pre-wrap;
}

[data-ui-component="ai-agent-request"] [data-ui-part="tool"],
[data-ui-component="ai-agent-request"] legend,
[data-ui-component="ai-agent-request"] small {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

[data-ui-component="ai-agent-request"] fieldset {
  display: flex;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  flex-direction: column;
  gap: 0.25rem;
}

[data-ui-component="ai-agent-request"] fieldset > strong {
  padding: 0.375rem;
}

