layoutAdaptations.after:
[data-ui-component="ai-agent-request"] {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  --ui-card-background: var(--ui-agent-request-background, var(--card));
  --ui-card-border-color: var(--ui-agent-request-border, var(--border));
  --ui-card-radius: var(--ui-agent-request-radius, 0.75rem);
}
.agent-request-card {
  min-width: 0;
  gap: var(--ui-agent-request-gap, var(--ui-ai-request-gap, 0.75rem));
  padding: var(--ui-agent-request-padding, 1rem);
  box-shadow: none;
  font-size: var(--ui-agent-request-text-size, 0.8125rem);
}
.agent-request-heading {
  display: flex;
  align-items: flex-start;
  gap: var(--ui-agent-request-heading-gap, 0.75rem);
  padding: 0;
}
.agent-request-heading-text {
  flex: 1;
  min-width: 0;
}
.agent-request-title {
  margin: 0;
  font-size: var(--ui-agent-request-title-size, 0.875rem);
  font-weight: 600;
  line-height: 1.45;
}
.agent-request-description {
  margin-block-start: 0.125rem;
  color: var(--muted-foreground);
  font-size: inherit;
  line-height: 1.5;
}
.agent-request-emblem {
  display: grid;
  place-items: center;
  flex: none;
  width: var(--ui-agent-request-icon-size, 2.5rem);
  height: var(--ui-agent-request-icon-size, 2.5rem);
  border-radius: var(--radius-lg);
  background: var(--ui-agent-request-icon-background, var(--muted));
  color: var(--primary);
}
.agent-request-emblem svg {
  width: 1.25rem;
  height: 1.25rem;
}
.agent-request-content {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0;
}
.agent-request-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: var(--ui-agent-request-action-gap, 0.5rem);
  padding: 0;
}
.agent-permission-resources {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin: 0;
  padding: 0.625rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--ui-agent-request-detail-background, var(--muted));
  list-style: none;
}
.agent-permission-resources li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}
.agent-permission-resources svg {
  width: 0.875rem;
  height: 0.875rem;
  flex: none;
  color: var(--muted-foreground);
}
.agent-permission-resources code {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}
.agent-permission-resources li > span:last-child {
  margin-inline-start: auto;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  text-align: end;
}
.agent-request-outcome {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.625rem;
  border-radius: var(--radius-md);
  background: var(--muted);
}
.agent-request-outcome svg {
  flex: none;
  width: 1rem;
  height: 1rem;
}
.agent-request-outcome time {
  margin-inline-start: auto;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}
[data-ui-component="ai-agent-request"][data-state="approved"]
  .agent-request-emblem,
[data-ui-component="ai-agent-request"][data-state="approved"]
  .agent-request-outcome {
  color: var(--ui-agent-request-success, var(--foreground));
  background: color-mix(
    in srgb,
    var(--success, var(--primary)) 10%,
    var(--card)
  );
}
[data-ui-component="ai-agent-request"][data-state="denied"]
  .agent-request-emblem,
[data-ui-component="ai-agent-request"][data-state="denied"]
  .agent-request-outcome,
[data-ui-component="ai-agent-request"][data-state="refused"]
  .agent-request-outcome {
  color: var(--ui-agent-request-destructive, var(--foreground));
  background: color-mix(in srgb, var(--destructive) 10%, var(--card));
}
.agent-question-fields {
  gap: 1rem;
}
.agent-question-field {
  gap: 0.5rem;
}
.agent-question-options {
  display: flex;
  flex-direction: column;
  gap: var(--ui-agent-request-option-gap, 0.5rem);
}
.agent-question-option {
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
  gap: 0.75rem;
  padding: var(--ui-agent-request-option-padding, 0.75rem);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  font: inherit;
}
.agent-question-option[data-selected="true"] {
  border-color: var(--primary);
  background: var(
    --ui-agent-request-selected-background,
    color-mix(in srgb, var(--primary) 8%, var(--card))
  );
}
.agent-question-option:has(:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.agent-question-option:has(:disabled) {
  cursor: not-allowed;
  opacity: 0.6;
}
.agent-question-option > span:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.125rem;
}
.agent-question-option small {
  font-size: 0.75rem;
  font-weight: 400;
  line-height: 1.4;
  color: var(--muted-foreground);
}
.agent-question-count {
  align-self: flex-end;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
}
@container (min-width: 30rem) {
  .agent-request-content,
  .agent-request-actions {
    margin-inline-start: calc(
      var(--ui-agent-request-icon-size, 2.5rem) +
        var(--ui-agent-request-heading-gap, 0.75rem)
    );
  }
}
[data-ui-component="ai-agent-request"] {
  container-type: inline-size;
}
@media (forced-colors: active) {
  .agent-question-option[data-selected="true"] {
    outline: 2px solid Highlight;
  }
}

