}
.agent-question-options {
  display: flex;
  flex-direction: column;
  gap: var(--ui-agent-request-option-gap, 0.5rem);
}
.agent-question-option {
  background: var(--ui-agent-request-option-background, var(--background));
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
  gap: 0.75rem;
  padding: var(--ui-agent-request-option-padding, 0.75rem);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  font: inherit;
}
.agent-question-option[data-selected="true"] {
  border-color: var(--primary);
  background: var(--ui-agent-request-selected-background, var(--background));
}
.agent-question-option:has(:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.agent-question-option:has(:disabled) {
  cursor: not-allowed;
  opacity: 0.6;
}
.agent-question-option > span:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.125rem;
}
.agent-question-option small {
  font-size: 0.75rem;
  font-weight: 400;
  line-height: 1.4;
  color: var(--muted-foreground);
}
