layoutAdaptations.before:
{#if query}
  <div class="store-history-query" aria-busy={query.pending}>
    <SearchFilterInput
      value={query.draft}
      inputMode="custom"
      showSearchIcon={false}
      ariaLabel={operations ? "Filter operation history" : "Filter JJ history"}
      placeholder={operations
        ? 'description:"rebase" user:steve'
        : 'mutable() & description("fix")'}
      editorExtensions={extensions}
      error={query.error || null}
      onValueChange={query.setDraft}
      onClearSearch={query.clear}
    >
      {#snippet actions()}
        <Button
          size="icon"
          variant="ghost"
          class="store-history-query__round"
          onclick={() => void query.run()}
          aria-label="Run history query"
          title="Run history query"><SearchIcon aria-hidden="true" /></Button
        >
        <Button
          size="icon"
          variant={contextOpen ? "default" : "ghost"}
          class="store-history-query__round"
          aria-label="Query context and syntax"
          title="Query context and syntax"
          aria-expanded={contextOpen}
          aria-controls="history-query-context"
          onclick={() => (contextOpen = !contextOpen)}
          ><SettingsIcon aria-hidden="true" /></Button
        >
      {/snippet}
    </SearchFilterInput>
    <Collapsible.Root open={contextOpen}>
      <Collapsible.Content id="history-query-context"
        ><StoreHistoryQueryContext {controller} /></Collapsible.Content
      >
    </Collapsible.Root>
    {#if query.pending}<div
        role="status"
        aria-label="Searching history"
        aria-busy="true"
      >
        <Skeleton style="height: 1rem; width: 100%" />
      </div>{/if}
  </div>
{/if}

{#if fileTreeOpen}<AppShell.Body.Sidebar
    panelId="repository-file-tree"
    side="left"
    label="Repository file tree"
    mobileLabel="Repository file tree"
    open={fileTreeOpen}
    scrollbarVisibility="hover"
    class="community-projects__file-tree-region"
    style={fileTreeStyle}
  >
    {#if initialLoading}<CommunityProjectsRepositorySkeleton
        layout="file-tree"
        label="Loading repository file tree"
      />{:else}<CommunityProjectsRepositoryFileTree
        files={view.snapshot?.files ?? []}
        directories={view.snapshot?.directories ?? []}
        mode={view.fileViewMode}
        collapsedDirectoryPaths={view.collapsedDirectoryPaths}
        selectedPath={view.route.path ?? ""}
        hasMore={view.canLoadMoreFiles}
        loading={view.status.files === "refreshing"}
        onSelectPath={controller.actions.selectFile}
        onLoadMore={() => void controller.actions.loadMore("files")}
        onModeChange={(mode) => void controller.actions.setFileViewMode(mode)}
        onDirectoryToggle={(path) =>
          void controller.actions.toggleDirectory(path)}
      />{/if}
  </AppShell.Body.Sidebar>
  <button
    type="button"
    class="community-projects__file-tree-resize"
    data-resizing={resizePointerId === null ? undefined : ""}
    data-min-width={fileTreeMinimum}
    data-max-width={fileTreeMaximum}
    data-current-width={fileTreeWidth}
    aria-label="Resize repository file tree"
    title="Drag to resize. Double-click to reset width."
    onpointerdown={beginFileTreeResize}
    onpointermove={moveFileTreeResize}
    onpointerup={finishFileTreeResize}
    onpointercancel={finishFileTreeResize}
    ondblclick={() => (fileTreeWidth = repositoryFileTreeDefaultWidth)}
    onkeydown={resizeFileTreeWithKeyboard}
  >
    <span aria-hidden="true"></span>
  </button>{/if}
<AppShell.Body.Content
  label="Repository file browser"
  scrollbarVisibility="hover"
  class="community-projects__files-content"
>
  <section
    class="community-projects__files-surface"
    aria-label="Repository files"
  >
    <CommunityProjectsRepositoryBreadcrumb
      {controller}
      editing={editing && view.repository.profile !== "git_sha1_jj045"}
      bind:filename={editFilename}
    />
    {#if initialLoading || directoryLoading}<CommunityProjectsRepositorySkeleton
        layout={view.route.path ? "source" : "directory"}
        path={view.route.path ?? ""}
        label="Loading repository files"
      />{:else}
      {#if view.targets.length > 1}<StoreNotice
          noticeKey="bookmark-target-selection"
          severity="warning"
          title="Choose a bookmark target"
          message="This bookmark is conflicted. Select an explicit revision to browse its files."
        />
        <div role="group" aria-label="Choose a bookmark target">
          {#each view.targets as target}<Button
              variant="outline"
              onclick={() => controller.actions.selectRevision(target)}
              >Open target {target.slice(0, 8)}…{target.slice(-4)}</Button
            >{/each}
        </div>{/if}
      {#if view.route.path}<CommunityProjectsRepositoryFilePanel
          {controller}
          bind:editing
          bind:filename={editFilename}
          blob={view.blob}
          selectedPath={view.route.path ?? ""}
          {latestCommit}
          {now}
          {fileTreeOpen}
          onToggleFileTree={() => (fileTreeOpen = !fileTreeOpen)}
          loading={view.status.detail === "loading"}
          isMarkdown={isMarkdownRepositoryPath(view.route.path ?? "")}
        />{:else}<CommunityProjectsRepositoryDirectory
          bind:fileTreeOpen
          currentPath={view.route.directory}
          {entries}
          {latestCommit}
          {pathCommits}
          canLoadPathCommit={true}
          metadataStatus={view.fileRevisionStatus}
          {previewDocuments}
          {editUnavailable}
          branch={selectedSnapshot}
          branches={snapshotChoices}
          {now}
          onOpenDirectory={controller.actions.selectDirectory}
          onOpenFile={controller.actions.selectFile}
          onEditFile={editLandingDocument}
          onSelectCommit={async (revision) => {
            await controller.actions.selectPage("log");
            await controller.actions.selectRevision(revision.eventId);
          }}
          onSelectBranch={selectSnapshot}
          hasMore={view.canLoadMoreFiles}
          loading={view.status.files === "refreshing"}
          onLoadMore={() => controller.actions.loadMore("files")}
          hasMoreReferences={view.canLoadMoreBookmarks}
          loadingReferences={view.status.bookmarks === "refreshing"}
          onLoadMoreReferences={() =>
            void controller.actions.loadMore("bookmarks")}
        />{/if}
    {/if}
  </section>
</AppShell.Body.Content>

layoutAdaptations.after:
{#snippet treeHeader(controls: Snippet)}<AppShell.Toolbar
    label="Repository files header"
    style="min-height:var(--ui-shell-toolbar-height);margin-inline:-0.5rem;--ui-shell-toolbar-padding-inline:0.5rem;--ui-shell-toolbar-padding-block:0"
    >{@render controls()}</AppShell.Toolbar
  >{/snippet}

<div class="repository-browser-screen">
  <RepositoryShell>
    <section class="repository-browser-layout" aria-label="Repository browser">
      {#if fileTreeOpen}
        <AppShell.Body.Sidebar
          panelId="repository-file-tree"
          side="left"
          label="Repository file tree"
          mobileLabel="Repository file tree"
          bind:open={fileTreeOpen}
          scrollbarVisibility="hover"
          class="repository-browser__file-tree-region"
          style={`--ui-shell-body-sidebar-width:${clamp(fileTreeWidth)}px`}
        >
          {#if view.directoryPhase === "loading" && !entries.length}<RepositorySkeleton
              kind="files"
              label="Loading repository file tree"
            />
          {:else}<RepositoryFileTree
              {files}
              header={treeHeader}
              {directories}
              mode={view.mode}
              collapsedDirectoryPaths={view.collapsedDirectoryPaths}
              selectedPath={view.path}
              hasMore={!!view.pages[pathPageKey("", view.mode !== "tree")]
                ?.nextCursor &&
                !view.pages[pathPageKey("", view.mode !== "tree")]
                  ?.limitReached}
              loading={treeLoading}
              onSelectPath={(path) => void controller.openFile(path)}
              onLoadMore={() => void controller.more("", view.mode !== "tree")}
              onModeChange={(mode) => void controller.setMode(mode)}
              onDirectoryToggle={(path) =>
                void controller.toggleDirectory(
                  path,
                  !view.collapsedDirectoryPaths.has(path),
                )}
            >
              {#snippet empty()}<RepositoryBrowserEmpty
                  folder
                  title="No repository files"
                  description="The selected revision has no loaded files."
                />{/snippet}
            </RepositoryFileTree>{/if}
        </AppShell.Body.Sidebar>
        <RepositorySidebarResize
          bind:width={fileTreeWidth}
          label="Resize repository file tree"
          onResize={saveLayout}
        />
      {/if}
      <AppShell.Body.Content
        label="Repository file browser"
        scrollbarVisibility="hover"
        class="repository-browser__files-content"
      >
        <section
          class="repository-browser__files-surface"
          aria-label="Repository files"
        >
          <AppShell.Toolbar
            label="Repository path header"
            class="repository-browser-toolbar"
            style="min-height:var(--ui-shell-toolbar-height);--ui-shell-toolbar-padding-inline:0;--ui-shell-toolbar-padding-block:0"
          >
            <RepositoryBreadcrumb
              {repositoryName}
              path={view.path ?? view.directory}
              onOpenDirectory={(path) => void controller.openDirectory(path)}
              {onOpenRepository}
            />{@render headerActions?.(selection)}
          </AppShell.Toolbar>
          {#if view.path}
            <RepositoryFilePreview
              file={view.file}
              phase={view.filePhase}
              {selection}
              display={view.display}
              {now}
              {fileTreeOpen}
              onToggleFileTree={toggleFileTree}
              onDisplayChange={(display) => controller.setDisplay(display)}
              onRetry={() => void controller.openFile(view.path!, true)}
              {onHistory}
              {onBlame}
              {blame}
              {copyText}
              actions={fileActions}
            />
          {:else}<RepositoryDirectory
              bind:fileTreeOpen
              onToggleFileTree={toggleFileTree}
              {now}
              currentPath={view.directory}
              entries={window?.entries ?? []}
              latestCommit={window?.latestCommit}
              documents={window?.documents}
              phase={view.directoryPhase}
              hasMore={!!window?.nextCursor && !window.limitReached}
              loading={view.directoryPhase === "loading"}
              limitReached={window?.limitReached ?? false}
              onOpenDirectory={(path) => void controller.openDirectory(path)}
              onOpenFile={(path) => void controller.openFile(path)}
              {onSelectCommit}
              onLoadMore={() => void controller.more()}
              onRetry={() => void controller.refresh()}
              {copyText}
              controls={directoryControls}
              actions={directoryActions}
              {rowActions}
            />{/if}
        </section>
      </AppShell.Body.Content>
      {#if inspector && view.path}<RepositorySidebarResize
          side="right"
          bind:width={inspectorWidth}
          minimum={280}
          maximum={800}
          defaultWidth={480}
          label="Resize file history sidebar"
          onResize={onInspectorResize}
        /><AppShell.Body.Sidebar
          side="right"
          panelId="repository-file-inspector"
          label="File inspector"
          style={`--ui-shell-body-sidebar-width:${Math.min(800, Math.max(280, Number.isFinite(inspectorWidth) ? inspectorWidth : 480))}px;background:var(--background)`}
          scrollbarVisibility="hover"
          >{@render inspector(selection)}</AppShell.Body.Sidebar
        >{/if}
    </section>
  </RepositoryShell>
</div>

